#!/usr/bin/env python3
"""Render the Docker Labs report from retained committed measurement snapshots."""
from pathlib import Path
import json,statistics,html,hashlib
R=Path(__file__).resolve().parents[1];D=R/'content/sites/docker/data'
def load(name):return json.loads((D/name).read_text())
def fmt(x,places=2):return f'{x:.{places}f}'
def median(rows,key='wall_s'):return statistics.median(r[key] for r in rows)
def select(rows,p,case=None):return [r for r in rows if r['project']==p and (case is None or r['case']==case)]
def nested(rows,path):
 values=[]
 for row in rows:
  value=row
  for key in path.split('.'):value=value[key]
  values.append(value)
 return statistics.median(values)
def esc(s):return html.escape(str(s))
initial=load('initial-warm.json');warm=load('optimized-warm.json');fresh=load('optimized-fresh.json');changes=load('changed.json');oldchanges=load('initial-changed.json')
assert len(initial)==15 and len(warm)==10 and len(fresh)==10 and len(changes)==60
assert all(r['fresh_equals_accepted'] for r in fresh)
assert all(r['semantic_output_checked'] for r in changes) and sum(r['incremental_equals_full'] for r in changes)==12
for name in ['human-browser.json','agent-browser.json']:
 v=load(name);assert v['states']==v['unique_states']==192 and not v['dom_differences'] and not v['behavior_differences'] and all(r['pixel_identical'] for r in v['visual'])
assert len(load('route-lifecycle.json'))==6 and all(r['incremental_equals_full'] for r in load('route-lifecycle.json'))
for p in ['docker','docker-agent']:assert load('accepted-hash-proof.json')[p]['all_publication_files_byte_identical']==8622
expected={'hugo':(29.12,34.46,1532.8),'docker':(21.83,23.75,441.6),'docker-agent':(14.65,15.20,391.7)}
current=[]
for p in expected:
 w=select(initial if p=='hugo' else warm,p);f=select(load('initial-fresh.json') if p=='hugo' else fresh,p)
 values=(median(w),median(f),median(w,'peak_rss_kib')/1024)
 assert tuple(round(v,2 if i<2 else 1) for i,v in enumerate(values))==expected[p],(p,values)
 current.append({'code':p,'name':'Hugo' if p=='hugo' else 'Nift '+p,'warm':values[0],'fresh':values[1],'memory':values[2],'warm_range':(min(r['wall_s'] for r in w),max(r['wall_s'] for r in w)),'fresh_range':(min(r['wall_s'] for r in f),max(r['wall_s'] for r in f)),'rss_range':(min(r['peak_rss_kib'] for r in w)/1024,max(r['peak_rss_kib'] for r in w)/1024)})
(D/'report.json').write_text(json.dumps({'pipelines':current,'derived_from':'Retained C6/C7 samples; generated by scripts/render_docker.py'},indent=2)+'\n')
HUMAN='https://github.com/nift-experiments/docker/blob/77f79f065e3076d02bf591ee41f487bbbaa038e9';AGENT='https://github.com/nift-experiments/docker-agent/blob/78e7817c780913601db8af54b396aa4392d0624a'
def link(url,label):return f'<a href="{url}">{label} ↗</a>'
def chapter(number,id,title,intro,body):return f'<section class="chapter" id="{id}" aria-labelledby="{id}-title"><div class="chapter-heading"><p class="eyebrow">{number} / {id.replace("-"," ")}</p><h2 id="{id}-title">{title}</h2><p class="section-intro">{intro}</p></div>{body}</section>'
def chart(key,title,scale,unit,caption):
 result=f'<figure class="chart"><figcaption><h3>{title}</h3><p>{caption}</p></figcaption><div class="axis" aria-hidden="true"><span>0</span><span>{scale/2:g}</span><span>{scale:g} {unit}</span></div>'
 for v in current:
  n=v[key];lo,hi=v['rss_range' if key=='memory' else key+'_range'];places=1 if key=='memory' else 2
  result+=f'<div class="chart-row {v["code"]}"><div class="chart-label"><span>{v["name"]}</span><strong>{fmt(n,places)} <small>{unit}</small></strong></div><div class="track" aria-hidden="true"><span style="width:{n/scale*100:.4f}%"></span></div><p class="range">5 runs · {fmt(lo,places)}–{fmt(hi,places)} {unit}</p></div>'
 return result+'</figure>'
parts=['''<header class="mast"><a class="brand" href="@path('/')"><span class="brand-mark" aria-hidden="true">≡</span> NIFT <span>LABS</span></a><nav aria-label="Report"><a href="#parity">Parity</a><a href="#benchmarks">Build costs</a><a href="#assessment">Agent assessment</a><a href="#evidence">Evidence</a></nav><a class="back" href="@path('sites/')">All experiments ↗</a></header>
<main id="main" class="wrap">
<section class="hero" aria-labelledby="report-title"><div><p class="eyebrow">Experiment 04 / Docker Docs / October 2026</p><h1 id="report-title">Same docs.<br>A different<br><em>build.</em></h1><p class="lede">A production documentation site, rebuilt as two Nift projects. Preserved Markdown for humans and agents. Maintained HTML for agents under human direction.</p><p>Docker Docs uses Hugo. We pinned its source and reconstructed the publication, routes, metadata, search, downloads, redirects and browser interactions. This is a real migration experiment with architecture and maintenance tradeoffs.</p><p class="independent">Independent Nift experiment. Not endorsed by Docker. Nift itself was not modified.</p></div><aside class="manifest" aria-label="Pinned publication manifest"><div class="manifest-top"><span>PUBLICATION MANIFEST</span><span class="verified">✓ ACCEPTED</span></div><div class="layer"><span>01 / HTML DOCUMENTS</span><strong>3,901</strong><p>Content, aliases, 404 and verification</p></div><div class="layer"><span>02 / CONTENT CORPUS</span><strong>2,170</strong><p>Including structured CLI/API references</p></div><div class="layer"><span>03 / RETRIEVAL OUTPUT</span><strong>2,142</strong><p>Searchable routes + synchronized downloads</p></div><div class="manifest-bottom"><span>SOURCE PIN</span><code>6cf1b1c167f0</code></div></aside></section>
<div class="report-map"><span>READ THE BUILD</span><a href="#parity">01 Proof</a><a href="#architectures">02 Sources</a><a href="#benchmarks">03 Measurements</a><a href="#maintenance">06 Maintenance</a></div>''']
parts.append(chapter('01','parity','Earn parity. Then measure.','Performance claims follow the acceptance gates. The full publication is the oracle, not a handful of similar-looking pages.','''<div class="proof-grid"><div><strong>8,622</strong><span>publication files per project</span></div><div><strong>3,901</strong><span>HTML documents</span></div><div><strong>2,170</strong><span>content pages + downloads</span></div><div><strong>2,142</strong><span>searchable routes</span></div><div><strong>31,268</strong><span>distinct search words</span></div><div><strong>192</strong><span>browser states per project</span></div></div><div class="proof-note"><span class="status">SHA-256 / PASSED</span><p>Every optimized publication file has the same SHA-256 as the accepted initial migration: <strong>all 8,622 files in each project</strong>. That proves optimization preserved the accepted migration; it does not claim every output byte equals Hugo.</p></div><div class="two-col"><div><h3>Publication + browser behavior</h3><p>All HTML route contracts and content-page comparisons pass. Search words, counts, metadata, filters, anchors and locations match. All 192 required screenshots per project are pixel-identical to the pinned reference, with zero tested DOM or behavior differences.</p><p>Checks cover responsive navigation, theme changes, search, tabs, accordions, copy controls, Gordon UI and API interactions.</p></div><div><h3>Changes have to publish correctly</h3><p>Route addition, rename and deletion pass. Previous outputs are retired; metadata, canonical links, navigation, TOC, downloads, sitemap and search remain coherent. Changed-input builds match forced full output, and all ten optimized fresh checkouts reproduce the accepted publication.</p><p>Nift 4.7.2 remains unchanged throughout.</p></div></div><details><summary>Accepted differences and validation boundaries</summary><div class="detail-body"><p>The migration retains accepted HTML-derived Markdown formatting, semantic XML whitespace equivalence and RSS generator attribution. Human Pagefind fragments differ in 144 sentence-boundary punctuation cases; the indexed route/word/metadata/anchor contracts match. Agent fragments match exactly.</p><p>Inherited upstream issues remain recorded: 576 missing descriptions, 2,154 duplicate-ID observations, 80 missing fragments, four missing local targets, 54 empty metadata URLs and 38 absent redirect targets. This pass introduces none.</p><p>Browser tests intercept remote requests. They establish tested local UI behavior, not live Docker AI, consent, telemetry or remote Redoc/backend availability. No prompts, feedback or telemetry were sent.</p>'''+link(HUMAN+'/investigation/C5-PARITY.md','Read the complete parity scope')+'</div></details>'))
parts.append(chapter('02','architectures','Two source models. One publication.','The distinction is intentional: the agent-primary pipeline has less transformation work because rendered HTML is maintained source.','''<div class="pipelines"><article class="pipeline human"><div class="pipeline-head"><span class="badge">HUMANS + AGENTS</span><h3>docker</h3><p>Keep the authored source.</p></div><ol><li>Maintained Markdown <small>Frontmatter + structured CLI/API sources</small></li><li>Docker compatibility renderer <small>Standalone Goldmark / Chroma + bounded ports</small></li><li>Transient HTML <small>Generated bodies, never the editorial source</small></li><li>Nift composition <small>Raw HTML + shared layouts + explicit dependencies</small></li><li>Publication + search <small>Minification, downloads, metadata, feeds, Pagefind</small></li></ol></article><article class="pipeline agent"><div class="pipeline-head"><span class="badge">AGENTS IMPLEMENT / HUMANS DIRECT</span><h3>docker-agent</h3><p>Maintain the rendered content.</p></div><ol><li>Maintained HTML <small>Rendered bodies + associated typed metadata</small></li><li>Nift composition <small>Raw HTML + shared layouts + explicit dependencies</small></li><li>Publication + search <small>Downloads, metadata, feeds, Pagefind</small></li></ol><p class="pipeline-foot">No routine Markdown renderer, generated-reference transformation or HTML minification stage. These are the maintained-HTML architecture’s disclosed boundaries.</p></article></div><div class="callout"><h3>A Docker compatibility layer, bounded by evidence.</h3><p>The human renderer implements the pinned corpus’s required shortcode/include behavior and seven render-hook categories, backed by real Docker fixtures. It does not attempt to recreate Hugo generally. Literal template/Nift-like syntax survives raw composition; mount and published-path normalization are explicit.</p><p>These timings are standalone compatibility rendering plus Nift orchestration/composition, <strong>not native <code>\\@markup</code> performance</strong>. The two pipelines are not equivalent authoring-model benchmarks.</p></div>'''))
parts.append(chapter('03','benchmarks','Count the whole build.','Five serialized samples per workflow. Medians and complete ranges, with publication and Pagefind included.','<div class="charts">'+chart('warm','Warm full pipeline',35,'s','Forced full build · elapsed median')+chart('fresh','Fresh committed checkout',35,'s','Empty application state/output · elapsed median')+chart('memory','Warm process/phase RSS',1600,'MiB','Median of each run’s largest measured process/phase maximum')+'</div><p class="chart-note">All bars use the labelled zero-origin linear scales. Ranges are min–max over five samples. RSS is an individual process/phase high-water mark, <strong>not aggregate simultaneous pipeline memory</strong>; parallel analysis workers require a different accounting boundary.</p><div class="trajectory"><div><span class="eyebrow">docker / warm full</span><p><span>61.52<small>s initial</small></span><b aria-hidden="true">→</b><strong>21.83<small>s optimized</small></strong></p></div><div><span class="eyebrow">docker-agent / warm full</span><p><span>30.27<small>s initial</small></span><b aria-hidden="true">→</b><strong>14.65<small>s optimized</small></strong></p></div></div><p>First we finished the faithful migration. Then we profiled and optimized it while preserving every accepted publication hash. The initial evidence is retained independently. Fresh medians also fell: <strong>66.66 → 23.75 s</strong> for docker and <strong>30.03 → 15.20 s</strong> for docker-agent.</p><p class="scope">This is a local production-workflow comparison. The migrations retain compiled upstream frontend assets; the native Hugo pipeline includes its generation/minification and asset work, flatten processing, API verification and Pagefind. Tool installation is outside timing. '+link('#methodology','Read the measurement boundaries')+'</p>'))
# Sequential outer-stage medians; nested renderer counters reported separately.
component_paths=[('Docker compatibility','compatibility_wall_s','docker'),('Shared shell','shell_prepare_s','docker'),('Composition preparation','composition_prepare_s','docker-agent'),('Joint body analysis','body_analysis.body_analysis_s','both'),('Nift composition','nift_composition_s','both'),('HTML minification','minification.html_minification_s','docker'),('Download write','publication.markdown_exports_s','both'),('Ancillary publication','publication.ancillary_s','both'),('Assets','asset_publication_s','both'),('Pagefind preparation + index','publication.search_s','both')]
rows=''
for label,path,scope in component_paths:
 values=[]
 for p in ['docker','docker-agent']:
  values.append('—' if scope not in ['both',p] else fmt(nested(select(warm,p),'components.'+path),3)+' s')
 rows+=f'<tr><th scope="row">{label}</th><td>{values[0]}</td><td>{values[1]}</td></tr>'
d=select(warm,'docker');nestedtext=', '.join(f'{label} <strong>{nested(d,"components.renderer_components_ns."+field)/1e9:.3f} s</strong>' for label,field in [('Markdown parse','MarkdownParseNS'),('Markdown render','MarkdownRenderNS'),('hooks','HookNS'),('Chroma','ChromaNS')])
parts.append(chapter('04','profiling','The expensive work surrounded the Markdown.','Raw Markdown parse/render was well under a second in the original human pipeline. Shared shell, repeated HTML analysis and minification explained much more of the total.','''<div class="optimization-list"><article><span>REUSE</span><h3>Prepare shared structure once.</h3><p>Navigation values/adjacency and invariant branches are reused. Templates are read once; generated route HTML is no longer retained in a large Python cache. Human shell preparation fell from <strong>16.19 to 2.68 s</strong>; agent preparation from <strong>15.62 to 3.53 s</strong>.</p></article><article><span>ANALYZE</span><h3>One body parse, two outputs.</h3><p>A shared four-worker analysis supplies heading bindings and Markdown downloads. Forced full builds still analyze/export all 2,170 pages. Export writes are now small because parsing/conversion is measured in joint analysis, not omitted.</p></article><article><span>BATCH</span><h3>Keep minification. Remove repetition.</h3><p>Eight human minifier workers and a bounded, exact-input SVG cache preserve output bytes. Minification fell from <strong>19.78 to 1.81 s</strong>. YAML reuse, safe C-backed loading and Chroma lexer reuse also reduce compatibility overhead.</p></article></div><div class="table-wrap" tabindex="0" role="region" aria-label="Optimized full-build component medians"><table><caption>Optimized warm full · five-run component medians</caption><thead><tr><th scope="col">Outer stage</th><th scope="col">docker</th><th scope="col">docker-agent</th></tr></thead><tbody>'''+rows+'</tbody></table></div><p class="nested">Nested inside the human compatibility stage: '+nestedtext+'. Typed CLI/API generation and shortcode expansion are included in that outer stage. Hook timing includes lexer discovery; Chroma measures tokenization/formatting.</p><p>Do not add nested counters twice. Parallel-worker wall sums are not elapsed stage time; component medians need not sum to the whole-pipeline median. Joint analysis includes HTML parsing and download conversion. Process startup and other orchestration also contribute.</p><div class="search-note"><span class="status">SEARCH / INCLUDED</span><h3>A correct index has a real fixed cost.</h3><p>Fresh Pagefind remains in every publication. Preparation and indexing are recorded separately; indexing costs roughly four seconds in the optimized runs. A narrower update needs a proven projection of every search-visible field. We retained correct full indexing instead of inventing incremental Pagefind behavior or dropping search from edit timings.</p></div>'+link(HUMAN+'/investigation/C6-OPTIMIZATION.md','Initial versus optimized component evidence')))
# Changed table has full, non-search project, and search medians for both source models.
changedrows=''
for case,label in [('1-page','1 body'),('10-pages','10 bodies'),('100-pages','100 bodies'),('layout','Shared footer'),('navigation','Navigation label'),('metadata','Title metadata')]:
 values=[]
 for p in ['docker','docker-agent']:
  a=select(changes,p,case);assert len(a)==5
  values.append(f'<strong>{fmt(median(a))} s</strong><small>{fmt(median(a,"project_work_s"))} project + {fmt(median(a,"search_s"))} search</small><small>Range {fmt(min(r["wall_s"] for r in a))}–{fmt(max(r["wall_s"] for r in a))} s</small>')
 changedrows+=f'<tr><th scope="row">{label}</th><td data-label="docker">{values[0]}</td><td data-label="docker-agent">{values[1]}</td></tr>'
parts.append(chapter('05','changed-inputs','An edit is a different workload.','Full builds regenerate the publication. Changed-input builds reuse unaffected work, then validate the result against a forced full rebuild.','<div class="table-wrap" tabindex="0" role="region" aria-label="Changed-input publication costs"><table class="edit-table"><caption>Publish-ready incremental builds · five edits per case · search included</caption><thead><tr><th scope="col">Change</th><th scope="col">docker</th><th scope="col">docker-agent</th></tr></thead><tbody>'+changedrows+'''</tbody></table></div><p>Project work is elapsed publication time minus measured search time. Separately calculated medians may not add exactly. Every case’s first edit equals forced full output; all 60 measured edits restore every original publication hash.</p><div class="two-col"><div><h3>Precise invalidation pays off.</h3><p>Human body edits compile exactly 1, 10 or 100 changed pages. Footer, navigation and title edits compile zero bodies. A title change no longer rerenders all 2,170 pages: its whole median fell from <strong>71.30 to 9.20 s</strong>. Footer fell from <strong>47.44 to 16.27 s</strong>; navigation from <strong>54.63 to 13.95 s</strong>.</p></div><div><h3>Small edits are still search-limited.</h3><p>One- and ten-page medians are slightly higher than the original migration in both projects. Full/shared-input gains do not mean every edit improved. Fresh search is retained, and these later active-desktop samples show higher indexing costs. Initial values and all ranges remain in the evidence.</p></div></div><p class="scope">The retained Hugo changed-input runs are <strong>full production CLI publications</strong>. They are not Hugo development-server hot reload. No claim is made that Hugo lacks development caching, or that these Nift edits beat its unmeasured server workflow.</p>'''))
parts.append(chapter('06','maintenance','Choose what you want to maintain.','Build time matters, but the maintained representation determines editing, review and ownership.','''<div class="maintenance-facts"><div><strong>323</strong><span>shared chrome templates</span></div><div><strong>4.55 MB</strong><span>shared chrome source</span></div><div><strong>4.27 MB</strong><span>same published JS in both</span></div></div><p>Both use explicit route, navigation and metadata models and preserve Docker’s frontend interactions. The ten published JavaScript files total 4,266,240 bytes in each project; these are uncompressed totals, not per-page downloads. A simpler build does not mean less shipped JavaScript.</p><div class="two-col maintenance-cards"><article><span class="badge">docker</span><h3>Conventional editorial source.</h3><p>Markdown/frontmatter remain familiar; readable diffs and structured CLI/API sources retain their authority. The source tree preserves useful Docker organization.</p><h4>The responsibility</h4><p>A Docker-specific compatibility layer, more transformation work and runtime dependencies. New corpus behavior requires a real fixture and a bounded port. Explicit family/route/metadata bindings and retained frontend assets must stay coherent.</p></article><article><span class="badge">docker-agent</span><h3>Rendered HTML as source.</h3><p>3,902 maintained HTML page files, including setup/auxiliary files, for 3,901 published documents. Agents edit rendered bodies directly; normal builds omit Markdown and source-derived reference generation.</p><h4>The responsibility</h4><p>Keep associated metadata, navigation and export state coherent. Specialized references are maintained rendered output. There is no conventional Markdown authoring workflow; human direction and review still matter.</p></article></div><p>Human routine tooling adds safe PyYAML, standalone Goldmark/Chroma/GoAT and pinned minification libraries. Agent routine builds use Python’s standard library, Nift and Pagefind. Both retain compiled upstream frontend assets; changing the frontend/tooling remains a separate engineering responsibility.</p>'''))
parts.append(chapter('07','assessment','What would this agent maintain?','An explicit engineering assessment from working on both implementations. These preferences are not measurements of long-term productivity or editing reliability.','''<div class="assessment"><article><span class="question">01 / AGENTS IMPLEMENT, HUMANS DIRECT</span><h3>I would choose docker-agent.</h3><p>For routine agent-led maintenance, removing content and generated-reference transformation makes the operational pipeline easier to reason about. Explicit HTML, shared structures and metadata mappings are workable for agents, and the materially smaller full-build cost makes repeated publication checks cheaper.</p><p>I would accept the duty to update related metadata and references coherently. Large source representations are manageable, but they still need review and parity/lifecycle gates.</p></article><article><span class="question">02 / HUMANS AND AGENTS BOTH EDIT</span><h3>I would choose docker.</h3><p>Markdown/frontmatter and structured CLI/API sources make ordinary human contributions more familiar and reviewable. I would keep those authoritative inputs rather than ask people to maintain rendered reference HTML. The optimized whole build is already below this experiment’s measured Hugo production pipeline.</p><p>The bounded compatibility code is a real maintenance cost. I would accept it for the demonstrated corpus, while requiring fixtures for new behavior and clear ownership of frontend/tooling changes.</p></article><article class="counterfactual"><span class="question">03 / BOTH ALREADY EXIST; NO MIGRATION DECISION</span><h3>The same source-model preference holds.</h3><p>If both implementations were already accepted, with equally available required services, I would maintain <strong>docker-agent for agent-only implementation under human direction</strong>, and <strong>docker for mixed human+agent editing</strong>. This preference excludes migration effort and incumbency; it follows the ongoing maintenance responsibilities.</p><p>We did not measure total agent cost, human editing effort or long-term productivity. Build feedback is only one part of the maintenance loop.</p></article></div>'''))
parts.append(chapter('08','official-migration','Worth a serious engineering evaluation.','Would this justify Docker investigating an official Nift migration? My assessment is yes. It does not establish that Docker should definitely migrate.','''<div class="verdict"><span class="status">AGENT JUDGMENT</span><h3>The benefits are substantial enough to investigate.</h3><p>The preserved-Markdown implementation improved full publication time and measured process/phase RSS while preserving the accepted corpus and tested browser behavior. Dependency-aware shared-input builds and successful route lifecycle checks make this more than a throughput demonstration.</p><p>The next decision belongs to Docker’s engineering workflow: weigh compatibility ownership, new-content discovery/validation, frontend regeneration, CI/deployment integration and moving away from an established Hugo toolchain. The smaller operational architecture of maintained HTML is attractive only if that authoring model fits.</p><p>I would propose a scoped engineering evaluation, with real contributor edits, frequent upstream changes and Docker’s actual CI/container deployment and service integrations. Production certification, team ergonomics and ongoing maintenance cost remain to be demonstrated. Performance alone does not establish universal superiority or justify an unqualified platform switch.</p></div>'''))
parts.append(chapter('09','methodology','Keep the boundaries attached.','A skeptical engineer should be able to identify the work, the retained state and the limits of each number.','''<dl class="method-grid"><div><dt>Upstream pin</dt><dd><code>6cf1b1c167f032e8a6629da211602300b623b20e</code><br>Docker’s public docs repository</dd></div><div><dt>Native reproduction</dt><dd>Production Hugo generation/minification → flatten tests/processing → API verification → Pagefind. Docker was unavailable on the host: this is not an Alpine/BuildKit benchmark.</dd></div><div><dt>Samples</dt><dd>Five serialized samples per workflow/case. Medians and min–max ranges. No fastest-run substitution; diagnostic/tuning trials remain separate.</dd></div><div><dt>Fresh state</dt><dd>Committed checkouts; empty application caches/output. Prepared binaries and dependencies, clone and validation excluded. OS caches uncontrolled: application-cold, not machine-cold.</dd></div><div><dt>Host + concurrency</dt><dd>Intel i7-12700H, 20 logical CPUs, about 61 GiB RAM. An active desktop, not an isolated server. Analysis: four workers; human minification: eight; original Nift threads −1.</dd></div><div><dt>Memory boundary</dt><dd>GNU time’s individual process/phase maxima; the page shows their five-run median. Not aggregate simultaneous pipeline RSS.</dd></div><div><dt>Toolchain</dt><dd>Nift 4.7.2 unchanged; Hugo extended 0.163.0; Node 24.21.0 / npm 11.19.0; Python 3.14.4. Standalone Go 1.26.0; upstream declares 1.26.8.</dd></div><div><dt>Full publication</dt><dd>Force content generation, Nift composition, analysis/downloads, human minification and search. Conditional copying of unchanged assets is retained. Frontend compilation and maintained source work differ between architectures.</dd></div></dl>'''))
parts.append(chapter('10','evidence','Open the repositories. Reproduce the work.','Frozen revisions and retained evidence make the claims inspectable. The experiment repositories were left unchanged while publishing this report.','<div class="evidence-grid"><article><span class="eyebrow">HUMAN + AGENT</span><h3>nift-experiments/docker</h3>'+link('https://github.com/nift-experiments/docker','Repository')+link(HUMAN+'/investigation/C7-COMPARISON.md','Final C7 comparison')+link(HUMAN+'/investigation/C6-OPTIMIZATION.md','Optimization and component evidence')+link(HUMAN.replace('/blob/','/tree/')+'/investigation/c6-optimized','Optimized samples and parity proofs')+link(HUMAN.replace('/blob/','/tree/')+'/investigation/c6','Preserved initial C6 evidence')+link(HUMAN.replace('/blob/','/tree/')+'/investigation/c7','Fresh samples and implementation commits')+'</article><article><span class="eyebrow">AGENT-PRIMARY</span><h3>nift-experiments/docker-agent</h3>'+link('https://github.com/nift-experiments/docker-agent','Repository')+link(AGENT+'/investigation/C7-COMPARISON.md','Final C7 comparison')+link(AGENT+'/README.md','Maintained-HTML build guide')+link('https://github.com/docker/docs/tree/6cf1b1c167f032e8a6629da211602300b623b20e','Pinned upstream source')+'</article></div><div class="reproduce"><h3>Run from the docker checkout, with both projects as siblings.</h3><p>Prepare pinned tools/dependencies using the README build guides before measuring. Use new evidence directories; retain accepted samples. Run sequentially:</p><pre tabindex="0" aria-label="Reproduction commands"><code>python3 benchmarks/run.py --projects docker,docker-agent --repetitions 5 --output ../docker-rerun/warm\npython3 benchmarks/changed.py --repetitions 5 --output ../docker-rerun/changed\npython3 benchmarks/fresh.py --projects docker,docker-agent --repetitions 5 --output ../docker-rerun/fresh\npython3 benchmarks/routes.py --output ../docker-rerun/routes</code></pre><p>The publication entry point is <code>python3 scripts/build.py</code>; use <code>--all</code> for forced full builds. Direct <code>nift build</code> composes already-prepared fragments only. Browser capture uses the documented pinned environment.</p></div>'))
parts.append('''<footer class="closing"><p class="eyebrow">Nift Labs / Independent engineering experiments</p><h2>Preserve the publication.<br><em>Choose the source.</em></h2><p>The result supports a practical question: which build architecture and authoring model would a team actually want to own?</p><a href="@path('sites/')">Explore the experiment notebook ↗</a><a href="#main">Back to the report ↑</a></footer></main>''')
(R/'content/sites/docker/index.html').write_text('\n'.join(parts)+'\n')
print('Docker report regenerated; headline values, samples, browser parity, lifecycle and fresh-hash proofs checked.')
